import threading

def reproduce(connect, service) -> str | None:
    amount = 1
    # Each round: N concurrent transfers, half 1->2 and half 2->1,
    # all starting at the same instant. Opposite lock order => deadlock.
    for _ in range(8):
        N = 8
        barrier = threading.Barrier(N)
        outcomes = [None] * N

        def do_transfer(idx):
            frm, to = (1, 2) if (idx % 2 == 0) else (2, 1)
            try:
                conn = connect()
            except Exception as e:
                outcomes[idx] = ("conn-fail", e)
                try:
                    barrier.wait(timeout=10)
                except Exception:
                    pass
                return
            try:
                barrier.wait(timeout=10)
            except Exception as e:
                outcomes[idx] = ("barrier", e)
                try:
                    conn.close()
                except Exception:
                    pass
                return
            try:
                service.transfer(conn, frm, to, amount)
                outcomes[idx] = ("ok", None)
            except Exception as e:
                msg = str(e).lower()
                if getattr(e, "sqlstate", None) == "40P01" or "deadlock" in msg:
                    outcomes[idx] = ("deadlock", e)
                else:
                    outcomes[idx] = ("other", e)
            finally:
                try:
                    conn.close()
                except Exception:
                    pass

        threads = [threading.Thread(target=do_transfer, args=(i,)) for i in range(N)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=30)

        for o, _ in outcomes:
            if o == "deadlock":
                return "deadlock detected: opposite transfers (1->2 vs 2->1) fail, payments rejected"
    return None

